/* Subcon03Mapper.selectMenuButtonAuthCnt */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_SYST_AUTH_MENU
     WHERE CMPNY_CD  = #{cmpnyCd}
       AND AUTH_CD   = #{authCd}
       AND MENU_D_ID = #{menuDId}
       AND USE_YN    = 'Y'

           AND BTN_SRCH = 'Y'
           AND BTN_NEW = 'Y'
           AND BTN_SAVE = 'Y'
           AND 1 = 0

     LIMIT 1
) T

/* Subcon03Mapper.selectChainSiteList */ SELECT T.siteCd AS siteCd , T.siteNm AS siteNm , T.chainDirection AS chainDirection FROM ( SELECT S.SITE_CD AS siteCd , S.SITE_NM AS siteNm , 'PROVIDE' AS chainDirection FROM TB_SITE S WHERE S.CMPNY_CD = #{gvCmpnyCd} AND IFNULL(S.USE_YN, 'Y') = 'Y' AND EXISTS ( SELECT 1 FROM TB_SITE_LINK L WHERE L.SRC_CMPNY_CD = #{gvCmpnyCd} AND L.SRC_SITE_CD = S.SITE_CD AND L.DST_CMPNY_CD = #{prvCmpnyCd} AND L.STATUS = 'ACTIVE' AND L.DST_SITE_CD IS NOT NULL )
UNION
SELECT S.SITE_CD AS siteCd , S.SITE_NM AS siteNm , 'RECEIVE' AS chainDirection FROM TB_SITE S WHERE S.CMPNY_CD = #{gvCmpnyCd} AND IFNULL(S.USE_YN, 'Y') = 'Y' AND S.LINK_SRC_CMPNY_CD = #{prvCmpnyCd} AND S.LINK_SRC_SITE_CD IS NOT NULL ) T ORDER BY T.siteNm ASC

/* Subcon03Mapper.selectMySiteActiveCnt */
SELECT COUNT(*)
FROM TB_SITE A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD  = #{siteCd}
  AND IFNULL(A.USE_YN, 'Y') = 'Y'

/* Subcon03Mapper.selectTargetSiteCdByChain */
SELECT T.targetSiteCd
FROM (
    SELECT L.DST_SITE_CD AS targetSiteCd
    FROM TB_SITE_LINK L
    WHERE L.SRC_CMPNY_CD = #{gvCmpnyCd}
      AND L.SRC_SITE_CD  = #{siteCd}
      AND L.DST_CMPNY_CD = #{prvCmpnyCd}
      AND L.STATUS       = 'ACTIVE'
      AND L.DST_SITE_CD IS NOT NULL

    UNION ALL

    SELECT S.LINK_SRC_SITE_CD AS targetSiteCd
    FROM TB_SITE S
    WHERE S.CMPNY_CD = #{gvCmpnyCd}
      AND S.SITE_CD  = #{siteCd}
      AND S.LINK_SRC_CMPNY_CD = #{prvCmpnyCd}
      AND S.LINK_SRC_SITE_CD IS NOT NULL
) T
LIMIT 1

/* Subcon03Mapper.selectRequestedDupCnt */
SELECT COUNT(*)
FROM TB_CMPNY_SHARE_REQ R
WHERE R.REQ_CMPNY_CD   = #{reqCmpnyCd}
  AND R.PRV_CMPNY_CD   = #{prvCmpnyCd}
  AND R.TARGET_SITE_CD = #{targetSiteCd}
  AND R.DATA_TYPE      = #{dataType}
  AND R.PERIOD_STR     = #{periodStr}
  AND R.PERIOD_END     = #{periodEnd}
  AND R.STATUS         = 'REQUESTED'

