/* Subcon03Mapper.insertShareReq */
INSERT INTO TB_CMPNY_SHARE_REQ (
      RELATION_ID
    , REQ_CMPNY_CD
    , REQ_SITE_CD
    , PRV_CMPNY_CD
    , TARGET_SITE_CD
    , DATA_TYPE
    , PERIOD_STR
    , PERIOD_END
    , CLOSED_ONLY_YN
    , PURPOSE
    , STATUS
    , REQ_USER_CD
    , INSERT_NO
    , INSERT_DATE
) VALUES (
      #{relationId}
    , #{reqCmpnyCd}
    , #{reqSiteCd}
    , #{prvCmpnyCd}
    , #{targetSiteCd}
    , #{dataType}
    , #{periodStr}
    , #{periodEnd}
    , #{closedOnlyYn}
    , #{purpose}
    , 'REQUESTED'
    , #{reqUserCd}
    , #{insertNo}
    , NOW()
)

