/* Subcon03Mapper.cancelShareReq */
UPDATE TB_CMPNY_SHARE_REQ
   SET STATUS           = 'CANCELLED'
     , PROCESS_CMPNY_CD = #{actorCmpnyCd}
     , PROCESS_USER_CD  = #{actorUserCd}
     , PROCESS_DTIME    = NOW()
     , PROCESS_COMMENT  = #{comment}
     , UPDATE_NO        = #{actorUserCd}
     , UPDATE_DATE      = NOW()
 WHERE SHARE_REQ_ID = #{shareReqId}
   AND STATUS       = 'REQUESTED'
   AND REQ_CMPNY_CD = #{actorCmpnyCd}

/* Subcon03Mapper.rejectShareReq */
UPDATE TB_CMPNY_SHARE_REQ
   SET STATUS           = 'REJECTED'
     , PROCESS_CMPNY_CD = #{actorCmpnyCd}
     , PROCESS_USER_CD  = #{actorUserCd}
     , PROCESS_DTIME    = NOW()
     , PROCESS_COMMENT  = #{comment}
     , UPDATE_NO        = #{actorUserCd}
     , UPDATE_DATE      = NOW()
 WHERE SHARE_REQ_ID = #{shareReqId}
   AND STATUS       = 'REQUESTED'
   AND PRV_CMPNY_CD = #{actorCmpnyCd}

/* Subcon03Mapper.approveShareReqPreempt */
UPDATE TB_CMPNY_SHARE_REQ
   SET STATUS           = 'APPROVED'
     , PROCESS_CMPNY_CD = #{actorCmpnyCd}
     , PROCESS_USER_CD  = #{actorUserCd}
     , PROCESS_DTIME    = NOW()
     , PROCESS_COMMENT  = #{comment}
     , UPDATE_NO        = #{actorUserCd}
     , UPDATE_DATE      = NOW()
 WHERE SHARE_REQ_ID = #{shareReqId}
   AND STATUS       = 'REQUESTED'
   AND PRV_CMPNY_CD = #{actorCmpnyCd}

