/* Subcon03Mapper.selectSiteNodeList */
SELECT
    N.NODE_CD    AS nodeCd
    , N.NODE_NM  AS nodeNm
FROM TB_SITE_NODE N
WHERE N.CMPNY_CD = #{cmpnyCd}
  AND N.SITE_CD  = #{siteCd}
ORDER BY N.NODE_CD ASC

/* Subcon03Mapper.selectCmpnyNm */
SELECT C.CMPNY_NM
FROM TB_CMPNY C
WHERE C.CMPNY_CD = #{cmpnyCd}

/* Subcon03Mapper.selectSiteNm */
SELECT S.SITE_NM
FROM TB_SITE S
WHERE S.CMPNY_CD = #{cmpnyCd}
  AND S.SITE_CD  = #{siteCd}

/* Subcon03Mapper.selectMaxSnapshotVersionByCondition */
SELECT IFNULL(MAX(S.VERSION), 0)
FROM TB_CMPNY_SHARE_SNAPSHOT S
    INNER JOIN TB_CMPNY_SHARE_REQ R
        ON (R.SHARE_REQ_ID = S.SHARE_REQ_ID)
WHERE R.REQ_CMPNY_CD   = #{reqCmpnyCd}
  AND R.PRV_CMPNY_CD   = #{prvCmpnyCd}
  AND R.TARGET_SITE_CD = #{targetSiteCd}
  AND R.DATA_TYPE      = #{dataType}
  AND R.PERIOD_STR     = #{periodStr}
  AND R.PERIOD_END     = #{periodEnd}

