/* Subcon03Mapper.selectRelayCandidates */ SELECT S.SNAPSHOT_ID AS snapshotId , R.PERIOD_STR AS periodStr , R.PERIOD_END AS periodEnd , CONCAT( LEFT(R.PERIOD_STR, 4), '-', MID(R.PERIOD_STR, 5, 2), '-', RIGHT(R.PERIOD_STR, 2) , ' ~ ' , LEFT(R.PERIOD_END, 4), '-', MID(R.PERIOD_END, 5, 2), '-', RIGHT(R.PERIOD_END, 2) ) AS periodLabel , S.VERSION AS version , S.ROW_CNT AS rowCnt , IFNULL(S.UNCLOSED_INCLUDED_YN, 'N') AS unclosedIncludedYn , DATE_FORMAT(S.CREATE_DTIME, '%Y-%m-%d %H:%i:%s') AS createDtime
, IFNULL(S.CLOSED_PARTIAL_YN, 'N') AS closedPartialYn FROM TB_CMPNY_SHARE_SNAPSHOT S INNER JOIN TB_CMPNY_SHARE_REQ R ON (R.SHARE_REQ_ID = S.SHARE_REQ_ID) WHERE S.OWNER_CMPNY_CD = #{ownerCmpnyCd} /* ① 내가 수신 보유한 스냅샷만 */ AND R.REQ_CMPNY_CD = #{ownerCmpnyCd} /* 소유 정합 이중 확인 */ AND R.REQ_SITE_CD = #{targetSiteCd} /* ② 같은 사업장 체인(내 사업장 기준 수신분) */ AND R.DATA_TYPE = #{dataType} /* ③ 동일 유형 + 기간 부분집합 */ AND R.PERIOD_STR >= #{periodStr} AND R.PERIOD_END <= #{periodEnd}
AND IFNULL(S.UNCLOSED_INCLUDED_YN, 'N') = 'N'
ORDER BY S.SNAPSHOT_ID DESC

