    , #{includedRcvSnapshotId}
    , #{ownerCmpnyCd}
    , #{rowCnt}
    , #{insertNo}
    , NOW()
)

mapper.select:
/* Subcon03Mapper.selectSnapshotList */ SELECT S.SNAPSHOT_ID AS snapshotId , S.SHARE_REQ_ID AS shareReqId , R.DATA_TYPE AS dataType , IFNULL(C.CMPNY_NM, '') AS srcCmpnyNm , IFNULL(MS.SITE_NM, '') AS siteNm , R.PERIOD_STR AS periodStr , R.PERIOD_END AS periodEnd , S.VERSION AS version , S.ROW_CNT AS rowCnt , IFNULL(S.UNCLOSED_INCLUDED_YN, 'N') AS unclosedIncludedYn , S.CONSENT_EXCLUDED_CNT AS consentExcludedCnt , DATE_FORMAT(S.CREATE_DTIME, '%Y-%m-%d %H:%i:%s') AS createDtime , CASE WHEN REL.RELATION_ID IS NOT NULL THEN 'Y' ELSE 'N' END AS relationActiveYn , R.PURPOSE AS purpose , CASE WHEN R.REQ_CMPNY_CD = S.OWNER_CMPNY_CD THEN IFNULL(NULLIF(RU.USER_NM, ''), R.REQ_USER_CD) ELSE NULL END AS reqUserNm , DATE_FORMAT(R.INSERT_DATE, '%Y-%m-%d %H:%i:%s') AS reqDtime , DATE_FORMAT(R.PROCESS_DTIME, '%Y-%m-%d %H:%i:%s') AS processDtime
, IFNULL(R.CLOSED_ONLY_YN, 'Y') AS closedOnlyYn , S.CLOSED_PARTIAL_YN AS closedPartialYn , S.COVERAGE_META AS coverageMeta FROM TB_CMPNY_SHARE_SNAPSHOT S INNER JOIN TB_CMPNY_SHARE_REQ R ON (R.SHARE_REQ_ID = S.SHARE_REQ_ID) LEFT OUTER JOIN TB_CMPNY C ON (C.CMPNY_CD = R.PRV_CMPNY_CD)
LEFT OUTER JOIN TB_SITE MS ON ( MS.CMPNY_CD = S.OWNER_CMPNY_CD AND MS.SITE_CD = R.REQ_SITE_CD ) LEFT OUTER JOIN TB_CMPNY_RELATION REL ON ( REL.RELATION_ID = R.RELATION_ID AND REL.STATUS = 'ACCEPTED' )
LEFT OUTER JOIN TB_USER RU ON ( RU.CMPNY_CD = R.REQ_CMPNY_CD AND RU.USER_CD = R.REQ_USER_CD AND R.REQ_CMPNY_CD = S.OWNER_CMPNY_CD ) WHERE S.OWNER_CMPNY_CD = #{gvCmpnyCd} ORDER BY S.SNAPSHOT_ID DESC LIMIT #{limit}

/* Subcon03Mapper.selectRequestedCntByRelation */
SELECT COUNT(*)
FROM TB_CMPNY_SHARE_REQ R
WHERE R.RELATION_ID = #{relationId}
  AND R.STATUS      = 'REQUESTED'

