/* Subcon03Mapper.selectMaxNearmissRowSeq */
SELECT IFNULL(MAX(N.ROW_SEQ), 0)
FROM TB_CMPNY_SHARE_SNAPSHOT_NEARMISS N
WHERE N.SNAPSHOT_ID = #{snapshotId}

/* Subcon03Mapper.selectMaxNearmissReporterSeq */
SELECT IFNULL(MAX(N.REPORTER_SEQ), 0)
FROM TB_CMPNY_SHARE_SNAPSHOT_NEARMISS N
WHERE N.SNAPSHOT_ID = #{snapshotId}

/* Subcon03Mapper.selectSnapshotFileRefCnt */
SELECT (
      (
        SELECT COUNT(1)
          FROM TB_CMPNY_SHARE_SNAPSHOT_RISK R
         WHERE R.SNAPSHOT_ID = #{snapshotId}
           AND (R.INIT_FILE_MGMT_CD = #{fileMgmtCd} OR R.REVAL_FILE_MGMT_CD = #{fileMgmtCd})
      )
    + (
        SELECT COUNT(1)
          FROM TB_CMPNY_SHARE_SNAPSHOT_RISK_IMPROVE I
         WHERE I.SNAPSHOT_ID  = #{snapshotId}
           AND I.FILE_MGMT_CD = #{fileMgmtCd}
      )
    + (
        SELECT COUNT(1)
          FROM TB_CMPNY_SHARE_SNAPSHOT_NEARMISS N
         WHERE N.SNAPSHOT_ID  = #{snapshotId}
           AND N.FILE_MGMT_CD = #{fileMgmtCd}
      )
) AS refCnt
FROM TB_CMPNY_SHARE_SNAPSHOT S
WHERE S.SNAPSHOT_ID    = #{snapshotId}
  AND S.OWNER_CMPNY_CD = #{gvCmpnyCd}

mapper.update:
/* Subcon03Mapper.cancelShareReqByRelation */
UPDATE TB_CMPNY_SHARE_REQ
   SET STATUS          = 'CANCELLED'
     , PROCESS_USER_CD = #{actionUserCd}
     , PROCESS_DTIME   = NOW()
     , PROCESS_COMMENT = '관계 해지에 따른 자동 취소'
     , UPDATE_NO       = #{actionUserCd}
     , UPDATE_DATE     = NOW()
 WHERE RELATION_ID = #{relationId}
   AND STATUS      = 'REQUESTED'
